-- The society must already exist, and exactly once. These were imported with
-- their flat counts and portal accounts, so a missing one is a mistake to
-- stop on rather than paper over by inserting a second row — and a DUPLICATE
-- one is worse, because every statement below matches by name and would
-- quietly write to both.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM societies WHERE name = 'Elite Homz';
  IF n = 0 THEN RAISE EXCEPTION 'no society named %', 'Elite Homz'; END IF;
  IF n > 1 THEN RAISE EXCEPTION '% societies named % — resolve the duplicate first', n, 'Elite Homz'; END IF;
END $$;

UPDATE societies SET status = 'active' WHERE name = 'Elite Homz';   -- address left as stored

INSERT INTO engagements (id, society_id, service_line, status, created_at)
SELECT 'bf-elite-homz-eng', s.id, 'lighting', 'active', now() FROM societies s WHERE s.name = 'Elite Homz' ON CONFLICT DO NOTHING;

INSERT INTO pipelines (id, society_id, service_line, stage, contact_name, contact_phone,
                       meeting_date, sales_owner_id, logged_by_id, authoritative, notes,
                       created_at, updated_at)
SELECT 'bf-elite-homz-pipe', s.id, 'lighting', 'active_billing',
       'Elite Homz', NULL, '2026-01-20'::date,
       a.id, a.id, true,
       'Backfilled from the signed agreement, the post-installation savings report and the first invoice. This deal predates the system: the date above is the agreement signature, not a meeting.',
       now(), now()
FROM societies s, admin_users a WHERE s.name = 'Elite Homz' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO site_surveys (id, pipeline_id, created_at) VALUES ('bf-elite-homz-survey', 'bf-elite-homz-pipe', now()) ON CONFLICT DO NOTHING;

