                          'deviations', '["eligibility-never-assessed", "dates-inferred-from-readings", "benchmark-single-demo"]'::jsonb,
                          'basisNote', '45 tube lights at 20W running 24h; theoretical 21.60 kWh/day against a measured 22.01, a +1.89% variance the report records as within range. NO OVERRIDE: (22.01-8.52)/22.01 = 61.2903%, which is the agreed 61.29%. Both tables reproduce their stated averages - 6 pre days 13-18 Nov 2025 average 22.0083 against 22.01, 6 post days 24-29 Nov average 8.5183 against 8.52. Neither date is stated: meter install taken as the day before the first pre-install reading (13 Nov 2025), replacement as the day before the post-install readings start (24 Nov).'),
       a.id, now()
FROM societies s, admin_users a WHERE s.name = 'Elite Homz' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;
