-- The demo report. Not needed for billing, but without it the deal map sits
-- at "Demo savings report · In progress" while every later step reads done.
INSERT INTO demo_reports (id, pipeline_id, version, status,
                          pre_install_baseline_total, post_install_average_total, measured_savings_pct,
                          society_light_count, metered_light_count, extrapolation_factor,
                          projected_savings_kwh_per_day, circuit_snapshot, generated_at, shared_at, shared_by_id)
SELECT 'bf-elite-homz-demo-report', 'bf-elite-homz-pipe', 1, 'shared',
       c.pre_install_baseline, c.pre_install_baseline * (1 - c.benchmark_savings_pct / 100),
       c.benchmark_savings_pct, c.represented_light_count, c.metered_light_count,
       c.represented_light_count::double precision / c.metered_light_count,
       (c.pre_install_baseline * c.benchmark_savings_pct / 100)
         * (c.represented_light_count::double precision / c.metered_light_count),
       '[{"circuitId": "bf-elite-homz-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 45, "representedLightCount": 961, "extrapolationFactor": 21.355556, "preInstallBaseline": 22.01, "postInstallAverage": 8.52, "savedKwhPerDay": 13.49, "benchmarkSavingsPct": 61.29, "projectedSavedKwhPerDay": 288.0849, "preInstallReadings": [], "postInstallReadings": []}]'::jsonb, now(), '2026-01-20'::date, a.id
FROM circuits c, admin_users a
-- shared_by_id is an ADMIN, not a profile: FirsThing shares the report WITH
-- the society, so the sharer is internal. The mirror of offers, where
-- responded_by_id IS a profile because accepting is the society's act.
WHERE c.id = 'bf-elite-homz-ckt-1' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO offers (id, pipeline_id, version, status, benchmark_source, circuit_terms,
                    tolerance_pct, revenue_share_pct, unit_electricity_rate, term_months,
                    projected_monthly_fee, issued_at, issued_by_id, responded_at, responded_by_id, created_at)
SELECT 'bf-elite-homz-offer', 'bf-elite-homz-pipe', 1, 'accepted', 'negotiated_fixed', '[{"circuitId": "bf-elite-homz-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 45, "representedLightCount": 961, "benchmarkSavingsPct": 61.29, "preInstallBaseline": 22.01, "projectedSavedKwhPerDay": 13.4899}]'::jsonb,
       5, 63, 7.00, 36,
       22394.00, '2026-01-20'::date, a.id,
       '2026-01-20'::date, p.id, now()
FROM admin_users a
LEFT JOIN societies soc ON soc.name = 'Elite Homz'
LEFT JOIN profiles p ON p.society_id = soc.id AND p.portal_authority = 'office_bearer' AND p.is_active
WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO agreements (id, pipeline_id, offer_id, prepared_at, prepared_by_id,
                        printed_at, notarized_at, signed_at, deviation_note,
                        executed_s3_key, executed_file_name, uploaded_at, uploaded_by_id)
SELECT 'bf-elite-homz-agreement', 'bf-elite-homz-pipe', 'bf-elite-homz-offer', '2026-01-20'::date, a.id,
       -- Printed and notarised are the same day, and it is the e-stamp
       -- certificate date on page 1 (the user, 2026-08-27). It can fall after
       -- the front-page date, which is a backdated effective date rather than
       -- a mistake.
       '2026-01-13'::date, '2026-01-13'::date,
       '2026-01-20'::date,
       -- How this deal's figures were arrived at, in the field named for it.
       -- These societies predate the system and share no single method, so
       -- the basis travels with the agreement rather than living in a CSV.
       'Commissioned before this system existed. There was no single method across these societies, so how this deal''s figures were arrived at is recorded here rather than assumed. Departures from the standard: extrapolation-measured, minimum-light-clause-not-enforced, report-share-differs-from-agreement. SOURCE IS THE USER''S PASTED TEXT for the agreement and demo report (2026-08-28); the invoices are real files. The demo was 45 lights - the annexure''s ''55'' is a typo, confirmed by the user, and 45 is what the report''s own theoretical (45 x 20W x 24h = 21.60 kWh/day) and every figure after it use. LIGHT COUNT IS 961, confirmed by the user (2026-08-28) after an initial 400. All three invoices bill 961, and the arithmetic agrees: April and May are full months at Rs 22,394.00, which is the agreement''s Rs 23,815 scaled 961/1022 to the rupee, and FirsThing''s share of the savings at 961 lights works out to exactly the 37% the agreement states. Agreement made 27 Dec 2025, notarised 13 Jan 2026, signed 20 Jan 2026. Billing from 15 Mar 2026: the first invoice is dated 31 Mar for 17 days, and installation finished on or before 14 Mar (the user), so this one follows CON-22''s ordinary day-after rule. Monthly charge is Rs 19,220 of devices (961 x Rs 20) plus Rs 3,174 of services = Rs 22,394 ex-GST; the March invoice prorates only the device line cleanly (19,220 x 17/31 = 10,540 exactly). 1,022 lights agreed, 961 installed - the agreement''s clause that the full Rs 23,815 stays payable below the minimum was NOT enforced; the charge was scaled down instead. Tolerance +/-5%, stated in clause 6. The demo report''s own ''50% of these verified savings'' does not match the agreement''s 63/37 and is not used.',
       'Documents/Elite_Homz/2026-01/Agreements/Elite_Homz_Agreement_2026-01-20.pdf',
       'Elite_Homz_Agreement_2026-01-20.pdf',
       -- The scan reaches us the day after signing.
       ('2026-01-20'::date + 1), a.id
FROM admin_users a WHERE a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

INSERT INTO contracts (id, pipeline_id, society_id, service_line, agreement_id, status,
                       term_start, term_end, activated_at, activated_by_id, created_at)
SELECT 'bf-elite-homz-contract', 'bf-elite-homz-pipe', s.id, 'lighting', 'bf-elite-homz-agreement', 'active',
       '2026-03-15'::date, ('2026-03-15'::date + '36 months'::interval),
       '2026-03-15'::date, a.id, now()
FROM societies s, admin_users a WHERE s.name = 'Elite Homz' AND a.id = 'sys-data-import' ON CONFLICT DO NOTHING;

