       '[{"circuitId": "bf-elite-homz-ckt-1", "lightType": "basement", "location": "Basement", "meteredLightCount": 45, "representedLightCount": 961, "benchmarkSavingsPct": 61.29, "preInstallBaseline": 22.01, "projectedSavedKwhPerDay": 13.4899}]'::jsonb, a.id, now()
